require_once 'functions.php';require_admin();$id=(int)($_GET['id']??0);$selected=(int)($_GET['user_id']??0);$row=['user_id'=>$selected,'purchase_date'=>date('Y-m-d'),'ml'=>'','notes'=>''];$error='';
