 if(!$valid->fetchColumn()||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$ml<=0)$error='Pilih member, tanggal yang valid, dan ukuran ML lebih dari 0.';
 else {if($id){$pdo->prepare('UPDATE purchases SET user_id=?,purchase_date=?,ml=?,notes=? WHERE id=?')->execute([$uid,$date,$ml,$notes,$id]);}else{$pdo->prepare('INSERT INTO purchases(user_id,purchase_date,ml,notes) VALUES(?,?,?,?)')->execute([$uid,$date,$ml,$notes]);}flash('Transaksi berhasil disimpan. Status hadiah dihitung otomatis berdasarkan urutan tanggal.');header('Location: purchases.php');exit;}
}
$pageTitle=$id?'Edit Transaksi':'Tambah Pembelian';$active='purchases';require 'header.php';
