<div class="form-card"><p class="eyebrow">CATATAN PEMBELIAN</p><h3><?=$id?'Ubah Transaksi':'Input Pembelian Member'?></h3><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Nama member *</label><select name="user_id" required><option value="">Pilih member</option><?php foreach($members as $m): ?><option value="<?=$m['id']?>" <?=((int)($_POST['user_id']??$row['user_id'])===$m['id'])?'selected':''?>><?=e($m['full_name'])?></option><?php endforeach; ?></select><label>Tanggal pembelian *</label><input type="date" name="purchase_date" value="<?=e($_POST['purchase_date']??$row['purchase_date'])?>" required><label>Ukuran parfum (ML) *</label><input type="number" name="ml" min="0.01" step="0.01" value="<?=e($_POST['ml']??$row['ml'])?>" placeholder="Contoh: 30" required><label>Catatan (opsional)</label><input name="notes" value="<?=e($_POST['notes']??$row['notes'])?>" placeholder="Contoh: parfum refill"><p class="muted small">Transaksi ke-5 dalam urutan tanggal dan ID akan ditandai gratis. Jika tanggal transaksi diedit, urutan reward dapat berubah.</p><div class="form-actions"><a class="btn outline" href="purchases.php">Batal</a><button class="btn primary">Simpan Transaksi</button></div></form></div>
